import datetime
import re

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.errors import NotFoundError, ValidationError, is_int
from tallybook.money import Money, format_minor
from tallybook.model import Posting, Transaction

__all__ = ["Ledger", "LedgerError"]

TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    """A transaction the ledger refuses."""


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _text_ok(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


def clean_tags(tags):
    if isinstance(tags, (str, bytes)) or tags is None:
        raise LedgerError("tags must be a list of tag names, got %r" % (tags,))
    try:
        items = list(tags)
    except TypeError:
        raise LedgerError("tags must be a list of tag names, got %r" % (tags,)) from None
    for t in items:
        if not isinstance(t, str) or not TAG_RE.fullmatch(t):
            raise LedgerError("invalid tag %r" % (t,))
    return tuple(sorted(set(items)))


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # ------------------------------------------------------------------ checks
    def _prepare(self, tx, used_ids, max_id, keep_id=None):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not _is_date(tx.date):
            raise LedgerError("invalid transaction date %r" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("invalid flag %r: expected * or !" % (tx.flag,))
        if not _text_ok(tx.payee):
            raise LedgerError("invalid payee %r" % (tx.payee,))
        if not _text_ok(tx.narration):
            raise LedgerError("invalid narration %r" % (tx.narration,))
        tags = clean_tags(tx.tags)
        try:
            postings = list(tx.postings)
        except TypeError:
            raise LedgerError("postings must be a list") from None
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _text_ok(p.note):
                raise LedgerError("invalid posting note %r" % (p.note,))
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("invalid posting amount %r" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        datestr = tx.date.isoformat()
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account if isinstance(p.account, str)
                                                          else repr(p.account)))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, datestr))
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            p = postings[i]
            new = [Posting(p.account, Money(-sums[c], c), p.note) for c in off]
            postings = postings[:i] + new + postings[i + 1:]
        elif off:
            raise LedgerError("transaction does not balance: %s"
                              % ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in off))
        for p in postings:
            acc = self.chart.get(p.account)
            if acc.currency is not None and p.amount.currency != acc.currency:
                raise LedgerError("account %s only holds %s, not %s" % (p.account, acc.currency, p.amount.currency))
        # id
        if keep_id is not None:
            if tx.id is not None and tx.id != keep_id:
                raise LedgerError("transaction id %r does not match %r" % (tx.id, keep_id))
            new_id = keep_id
        elif tx.id is None:
            new_id = max_id + 1
        else:
            if not is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in used_ids:
                raise LedgerError("transaction %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings, tags, tx.flag, new_id)

    # ---------------------------------------------------------------- changing
    def add(self, tx):
        stored = self._prepare(tx, self._txs, self._max_id)
        self._txs[stored.id] = stored
        self._max_id = max(self._max_id, stored.id)
        return stored

    def add_many(self, transactions):
        saved_txs = dict(self._txs)
        saved_max = self._max_id
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs = saved_txs
            self._max_id = saved_max
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %r" % (id,))
        stored = self._prepare(tx, self._txs, self._max_id, keep_id=id)
        self._txs[id] = stored
        return stored

    def get(self, id):
        try:
            return self._txs[id]
        except (KeyError, TypeError):
            raise NotFoundError("no transaction %r" % (id,)) from None

    def remove(self, id):
        tx = self.get(id)
        del self._txs[id]
        return tx

    # ----------------------------------------------------------------- reading
    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def balances(self, as_of=None):
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            d = out.setdefault(p.account, {})
            d[p.amount.currency] = d.get(p.amount.currency, 0) + p.amount.minor
        return _clean(out)

    def rollup_balances(self, as_of=None):
        out = {}
        for account, cur in self.balances(as_of).items():
            segs = account.split(":")
            for i in range(1, len(segs) + 1):
                d = out.setdefault(":".join(segs[:i]), {})
                for c, v in cur.items():
                    d[c] = d.get(c, 0) + v
        return _clean(out)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        self.chart.get(account)
        totals = {}
        prefix = account + ":"
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.account == account or (rollup and p.account.startswith(prefix)):
                totals[p.amount.currency] = totals.get(p.amount.currency, 0) + p.amount.minor
        if currency is not None:
            return Money(totals.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(totals.items()) if v != 0}


def _clean(out):
    result = {}
    for account in sorted(out):
        cur = {c: v for c, v in sorted(out[account].items()) if v != 0}
        if cur:
            result[account] = cur
    return result
"""CSV and JSON export, and the plain text table renderer."""

import json

from tallybook.currency import CurrencyError
from tallybook.dates import DateError, parse_date
from tallybook.errors import TallybookError, ValidationError, is_int
from tallybook.money import Money, parse_amount
from tallybook.model import Posting, Transaction

__all__ = ["transactions_to_csv", "transactions_to_json", "transactions_from_json", "render_table", "to_csv",
           "to_json", "money_to_dict", "transaction_to_dict", "ExportError"]


class ExportError(ValidationError):
    """A table or JSON document that cannot be handled."""


# ------------------------------------------------------------------- CSV
def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "\n".join(lines) + "\n"


def _date_text(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _tags(tx):
    return sorted(set(tx.tags or ()))


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, _date_text(tx.date), tx.flag, tx.payee, tx.narration, ";".join(_tags(tx))]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, "", "", p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# ------------------------------------------------------------------ JSON
def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": _date_text(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_dict(obj, where="amount"):
    """Read a money object {"amount": text, "currency": text}; ExportError otherwise."""
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: an amount must be an object with exactly 'amount' and 'currency'" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: 'amount' and 'currency' must be text" % where)
    try:
        return Money(parse_amount(obj["amount"], obj["currency"]), obj["currency"])
    except TallybookError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("expected a JSON array of transactions")
    out = []
    for i, item in enumerate(data, 1):
        where = "transaction %d" % i
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %r" % (where, k))
        if not isinstance(item["date"], str):
            raise ExportError("%s: invalid date %r" % (where, item["date"]))
        try:
            d = parse_date(item["date"])
        except DateError as e:
            raise ExportError("%s: %s" % (where, e.message)) from None
        tid = item.get("id")
        if tid is not None and (not is_int(tid) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_raw = item["postings"]
        if not isinstance(postings_raw, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for j, pr in enumerate(postings_raw, 1):
            pwhere = "%s posting %d" % (where, j)
            if not isinstance(pr, dict):
                raise ExportError("%s: not an object" % pwhere)
            for k in pr:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pwhere, k))
            if "account" not in pr or not isinstance(pr["account"], str):
                raise ExportError("%s: account missing or not text" % pwhere)
            amount = pr.get("amount")
            if amount is not None:
                amount = money_from_dict(amount, pwhere)
            note = pr.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pwhere)
            postings.append(Posting(pr["account"], amount, note))
        out.append(Transaction(d, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# ---------------------------------------------------------------- tables
def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    n = len(headers)
    if n == 0:
        return ""
    if align is None:
        aligns = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("invalid alignment %r" % (align,))
        aligns = list(align)
        if len(aligns) != n or any(a not in ("l", "r") for a in aligns):
            raise ExportError("invalid alignment %r for %d columns" % (align, n))
    body = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        body.append(cells)
    widths = [len(h) for h in headers]
    for cells in body:
        for i, c in enumerate(cells):
            widths[i] = max(widths[i], len(c))

    def line(cells):
        parts = [c.ljust(widths[i]) if aligns[i] == "l" else c.rjust(widths[i]) for i, c in enumerate(cells)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(c) for c in body)
    return "\n".join(out) + "\n"

"""Exact money: whole minor units and a currency code."""

import re

from tallybook.currency import CurrencyError, currency
