"""Reports: trial balance, balance sheet, income statement, cash flow, register, net worth."""

import datetime

from tallybook.accounts import ROOT_TYPES
from tallybook.currency import currency as _currency
from tallybook.dates import Period, periods
from tallybook.errors import ValidationError
from tallybook.export import money_to_dict, render_table, to_csv
from tallybook.ledger import Ledger
from tallybook.money import Money, round_div

__all__ = ["trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth",
           "render_text", "report_to_csv", "ReportError"]

REPORT_KINDS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")


class ReportError(ValidationError):
    """A report that cannot be made or drawn."""


# ---------------------------------------------------------------- helpers
def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _date_text(d):
    return None if d is None else "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _check_ledger(ledger):
    if not isinstance(ledger, Ledger):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not _is_date(as_of):
        raise ReportError("invalid date %r" % (as_of,))


def _check_period(period, optional=False):
    if period is None and optional:
        return
    if not isinstance(period, Period):
        raise ReportError("invalid period %r" % (period,))


def _check_convert_to(convert_to):
    if convert_to is not None:
        _currency(convert_to)  # CurrencyError as it is


def _type_of(path):
    return ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, code):
    return money_to_dict(Money(minor, code))


def _money_list(sums, keep_zero):
    """A list of money dicts from {currency: minor}, sorted by currency."""
    return [_m(v, c) for c, v in sorted(sums.items()) if keep_zero or v != 0]


def _account_lines(sums):
    """Sorted (account, currency, minor) for non-zero entries of {(account, currency): minor}."""
    return [(a, c, v) for (a, c), v in sorted(sums.items()) if v != 0]


def _add(d, key, value):
    d[key] = d.get(key, 0) + value


def _percent(part, total):
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    tenths = round_div(part * 1000, total)
    if tenths == 0:
        return "0.0"
    sign = "-" if tenths < 0 else ""
    a = abs(tenths)
    return "%s%d.%d" % (sign, a // 10, a % 10)


def _convert(ledger, minor, code, convert_to, on):
    return ledger.rates.convert(Money(minor, code), convert_to, on)


# ------------------------------------------------------------ trial balance
def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
            _add(sections[t], (p.account, cur), -v)
        elif t in ("income", "expense"):
            _add(retained, cur, -v)

    def section(kind):
        lines = []
        total = {}
        for account, cur, v in _account_lines(sections[kind]):
            if convert_to is None:
                lines.append({"account": account, "balance": _m(v, cur)})
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": account, "balance": money_to_dict(conv), "original": _m(v, cur)})
                _add(total, convert_to, conv.minor)
        return lines, total

    a_lines, a_total = section("asset")
    l_lines, l_total = section("liability")
    e_lines, e_total = section("equity")
    if convert_to is None:
        re_list = _money_list(retained, keep_zero=False)
        for c, v in retained.items():
            if v != 0:
                _add(e_total, c, v)
    else:
        nonzero = [(c, v) for c, v in sorted(retained.items()) if v != 0]
        re_list = []
        if nonzero:
            s = 0
            for c, v in nonzero:
                s += _convert(ledger, v, c, convert_to, as_of).minor
            re_list = [_m(s, convert_to)]
            _add(e_total, convert_to, s)
        for t in (a_total, l_total, e_total):
            t.setdefault(convert_to, 0)
    curs = set(a_total) | set(l_total) | set(e_total)
    balanced = all(a_total.get(c, 0) == l_total.get(c, 0) + e_total.get(c, 0) for c in curs)
    return {"report": "balance_sheet", "as_of": _date_text(as_of), "currency": convert_to,
            "assets": {"accounts": a_lines, "total": _money_list(a_total, True)},
            "liabilities": {"accounts": l_lines, "total": _money_list(l_total, True)},
            "equity": {"accounts": e_lines, "retained_earnings": re_list, "total": _money_list(e_total, True)},
            "balanced": balanced}


# --------------------------------------------------------- income statement
def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    _check_convert_to(convert_to)
    sums = {"income": {}, "expense": {}}
    for tx, p in ledger.postings():
        if not (period.start <= tx.date <= period.end):
            continue
        t = _type_of(p.account)
        if t == "income":
            _add(sums["income"], (p.account, p.amount.currency), -p.amount.minor)
        elif t == "expense":
            _add(sums["expense"], (p.account, p.amount.currency), p.amount.minor)

    def section(kind):
        raw = _account_lines(sums[kind])
        total = {}
        items = []
        for account, cur, v in raw:
            if convert_to is None:
                items.append((account, cur, v, None))
                _add(total, cur, v)
            else:
                conv = _convert(ledger, v, cur, convert_to, period.end)
                items.append((account, convert_to, conv.minor, _m(v, cur)))
                _add(total, convert_to, conv.minor)
        if convert_to is not None:
            total.setdefault(convert_to, 0)
        lines = []
        for account, cur, v, original in items:
            line = {"account": account, "amount": _m(v, cur), "percent": _percent(v, total[cur])}
            if original is not None:
                line["original"] = original
            lines.append(line)
        return lines, total

    i_lines, i_total = section("income")
    e_lines, e_total = section("expense")
    net = {c: i_total.get(c, 0) - e_total.get(c, 0) for c in set(i_total) | set(e_total)}
    return {"report": "income_statement", "start": _date_text(period.start), "end": _date_text(period.end),
            "currency": convert_to,
            "income": {"accounts": i_lines, "total": _money_list(i_total, True)},
            "expenses": {"accounts": e_lines, "total": _money_list(e_total, True)},
            "net": _money_list(net, True)}


# ----------------------------------------------------------------- cashflow
def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    opening, closing, flows = {}, {}, {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                cur = p.amount.currency
                closing.setdefault(cur, 0)
                opening.setdefault(cur, 0)
                closing[cur] += p.amount.minor
                if tx.date < period.start:
                    opening[cur] += p.amount.minor
        if tx.date < period.start:
            continue
        asset_sum = {}
        for p in tx.postings:
            if _type_of(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if _type_of(p.account) != "asset" and asset_sum.get(p.amount.currency, 0) != 0:
                _add(flows, (p.account, p.amount.currency), -p.amount.minor)
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for account, cur, v in _account_lines(flows):
        if v > 0:
            inflows.append({"account": account, "amount": _m(v, cur)})
            total_in[cur] = total_in.get(cur, 0) + v
        else:
            outflows.append({"account": account, "amount": _m(-v, cur)})
            total_out[cur] = total_out.get(cur, 0) - v
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in closing}
    return {"report": "cashflow", "start": _date_text(period.start), "end": _date_text(period.end),
            "opening": _money_list(opening, True), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in, True), "total_out": _money_list(total_out, True),
            "net": _money_list(net, True), "closing": _money_list(closing, True)}


# ----------------------------------------------------------------- register
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


# ---------------------------------------------------------------- net worth
def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    txs = ledger.transactions()
    points = []
    for st in steps:
        d = st.end
        assets, liabilities = {}, {}
        for tx in txs:
            if tx.date > d:
                break
            for p in tx.postings:
                t = _type_of(p.account)
                if t in ("asset", "liability"):
                    cur = p.amount.currency
                    assets.setdefault(cur, 0)
                    liabilities.setdefault(cur, 0)
                    if t == "asset":
                        assets[cur] += p.amount.minor
                    else:
                        liabilities[cur] -= p.amount.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": _date_text(d), "assets": _money_list(assets, True),
                       "liabilities": _money_list(liabilities, True), "net": _money_list(net, True)})
    return {"report": "net_worth", "start": _date_text(period.start), "end": _date_text(period.end),
            "step": step, "points": points}


# --------------------------------------------------------------- rendering
def _kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORT_KINDS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _mt(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(width, *blocks):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
    rows = [[a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
             _mt(a["credit"]) if a["credit"] else ""] for a in r["accounts"]]
    rows += [["Total", "", _mt(t["debit"]), _mt(t["credit"])] for t in r["totals"]]
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet"
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label, extra=()):
        sec = r[key]
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        b += list(extra)
        b += [[total_label, _mt(m)] for m in sec["total"]]
        return b

    rows = _blocks(2, block("assets", "Assets", "Total assets"),
                   block("liabilities", "Liabilities", "Total liabilities"),
                   block("equity", "Equity", "Total equity",
                         [["  Retained earnings", _mt(m)] for m in r["equity"]["retained_earnings"]]))
    return title, ["Account", "Balance"], rows, "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency"):
        title += " (in %s)" % r["currency"]

    def block(key, heading, total_label):
        sec = r[key]
        b = [[heading, "", ""]]
        b += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        b += [[total_label, _mt(m), ""] for m in sec["total"]]
        return b

    rows = _blocks(3, block("income", "Income", "Total income"),
                   block("expenses", "Expenses", "Total expenses"),
                   [["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], rows, "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def block(lines, totals, heading, total_label):
        b = [[heading, ""]]
        b += [["  " + a["account"], _mt(a["amount"])] for a in lines]
        b += [[total_label, _mt(m)] for m in totals]
        return b

    rows = _blocks(2, [["Opening balance", _mt(m)] for m in r["opening"]],
                   block(r["inflows"], r["total_in"], "Money in", "Total money in"),
                   block(r["outflows"], r["total_out"], "Money out", "Total money out"),
                   [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]])
    return title, ["Account", "Amount"], rows, "lr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for p in r["points"]:
        if not p["assets"]:
            rows.append([p["date"], "", "", ""])
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


_TEXT = {"trial_balance": _text_trial_balance, "balance_sheet": _text_balance_sheet,
         "income_statement": _text_income_statement, "cashflow": _text_cashflow,
         "net_worth": _text_net_worth, "register": _text_register}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], m["currency"], a["debit"]["amount"] if a["debit"] else "",
                     a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
    rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
    rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
    rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = [[row["date"], "" if row["id"] is None else row["id"], row["payee"], row["narration"], row["account"],
             row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]] for row in r["rows"]]
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {"trial_balance": _csv_trial_balance, "balance_sheet": _csv_balance_sheet,
        "income_statement": _csv_income_statement, "cashflow": _csv_cashflow,
        "net_worth": _csv_net_worth, "register": _csv_register}


def report_to_csv(report):
    kind = _kind(report)
    try:
        headers, rows = _CSV[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return to_csv(headers, rows)
